import { HttpClient, provideHttpClient } from '@angular/common/http';
import {
  EnvironmentProviders,
  inject,
  InjectionToken,
  makeEnvironmentProviders,
} from '@angular/core';
import { provideTranslateService, TranslateLoader } from '@ngx-translate/core';

import { MultiTranslateHttpLoader } from './multi-translate-http-loader';

const SAT_TRANSLATION_FILE_LOCATIONS = new InjectionToken<string[]>(
  'SAT_TRANSLATION_FILE_LOCATIONS',
);

export interface SatoriUILanguageConfig {
  fallbackLang?: string;
  /** @deprecated Use `fallbackLang` instead. */
  default?: string;
  /**
   * Optional configuration for language prefixes and suffixes.
   * See: https://ngx-translate.org/getting-started/translation-files/#loading-translations-dynamically
   */
  settings?: {
    prefix?: string;
    suffix?: string;
  };
}

const satoriUITranslationPath = '@hylandsoftware/satori-ui';

const httpLoaderFactory: (
  languageSettings?: SatoriUILanguageConfig['settings'],
) => (http: HttpClient) => TranslateLoader =
  (languageSettings: SatoriUILanguageConfig['settings']) => (http: HttpClient) => {
    const translationPaths =
      inject(SAT_TRANSLATION_FILE_LOCATIONS, { optional: true })?.flat() ?? [];
    return new MultiTranslateHttpLoader(
      http,
      languageSettings?.prefix ?? './i18n/',
      languageSettings?.suffix ?? '.json',
      translationPaths,
    );
  };

/**
 * Provides the default translation feature for the Satori UI library.
 * This sets up the translation loader to fetch translation files from the `./i18n/` directory
 * @param languageConfig Configuration for the default language of the application.
 */
export function provideAndConfigureSatoriUITranslations(
  languageConfig: SatoriUILanguageConfig,
): EnvironmentProviders {
  return makeEnvironmentProviders([
    provideHttpClient(),
    provideTranslateService({
      fallbackLang: languageConfig.fallbackLang ?? languageConfig.default,
      loader: {
        provide: TranslateLoader,
        useFactory: httpLoaderFactory(languageConfig.settings),
        deps: [HttpClient],
      },
    }),
    provideTranslations([satoriUITranslationPath]),
  ]);
}

// If translationPaths is not provided, it will fetch file directly from "./i18n/en-US.json"
export function provideTranslations(translationPaths: string[] = ['']): EnvironmentProviders {
  return makeEnvironmentProviders([
    {
      provide: SAT_TRANSLATION_FILE_LOCATIONS,
      useValue: translationPaths,
      multi: true,
    },
  ]);
}
